def relay_load_capacity(loads: list[int], rounds: int) -> int:
    low, high = max(loads), sum(loads)
    while low < high:
        capacity = (low + high) // 2
        used, current = 1, 0
        for load in loads:
            if current + load > capacity:
                used += 1
                current = 0
            current += load
        if used <= rounds:
            high = capacity
        else:
            low = capacity + 1
    return low

