def relay_load_capacity(loads: list[int], rounds: int) -> int:
    capacity = max(loads)
    while True:
        used, current = 1, 0
        for load in loads:
            if current + load > capacity:
                used += 1
                current = 0
            current += load
        if used <= rounds:
